def _dependency_solver(data, name_order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + versions)

    best_vector = None
    best = None
    for values in product(*choices):
        selected = dict(zip(names, values))
        selected = {name: version for name, version in selected.items()
                    if version is not None}
        if any(name not in selected or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue
        rows = {name: {row["version"]: row for row in packages[name]}[version]
                for name, version in selected.items()}
        active, finished, closure = set(), set(), set()
        valid = True

        def visit(name):
            nonlocal valid
            if name in active:
                return False
            if name in finished:
                return True
            if name not in selected:
                valid = False
                return False
            active.add(name)
            closure.add(name)
            for dep in rows[name].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = selected.get(other)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    active.remove(name)
                    return False
                if not visit(other):
                    active.remove(name)
                    return False
            active.remove(name)
            finished.add(name)
            return True

        for root in data["roots"]:
            if not visit(root):
                valid = False
                break
        if not valid or closure != set(selected):
            continue
        vector = tuple(selected.get(name, -1) for name in names)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector = vector
            best = selected
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _rounded(numerator, denominator, mode):
    quotient, remainder = divmod(numerator, denominator)
    if mode == "half_up" and 2 * remainder >= denominator:
        quotient += 1
    return quotient


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = _rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        if len(chosen) != data["k"]:
            continue
        ids = tuple(sorted(job["id"] for job in chosen))
        id_set = set(ids)
        if id_set & blocked or not mandatory.issubset(id_set):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in chosen:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
    return {"arrival": None}


